      SUBROUTINE MIDENTCC     IDENTIFIES POSITION OF MISALIGNMENTS ASSOCIATED WITH EACH UPDATECC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0D.CIN'      INCLUDE 'ELM0F.CIN'      INCLUDE 'ELM8A.CIN'      INCLUDE 'ELM8F.CIN'      INCLUDE 'ELM8G.CIN'      INCLUDE 'ELM8H.CIN'      INCLUDE 'ELM8M.CIN'      INCLUDE 'ELM9.CIN'      INCLUDE 'ELM24A.CIN'      INCLUDE 'ELM31A.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'INDPAR.CIN'CC     LOCAL VARIABLESC      INTEGER         TYPES      EQUIVALENCE     (FAKE,LAKE)      EXTERNAL        IDATAC------------------------------------------------------------------C      NUM = 1      NDIF = 1      ALO(1) = .FALSE.      ALO(2) = .FALSE.      NM = 0      NUP(2) = 0      NUP(3) = 0      NIU(2) = 0      NIU(3) = 0      DO 5 N = 1, 10    5 NMTE(N) = 0      ATWORK = NUSE .EQ. 0C      IF (NEL .LE. 0) GO TO 5300   10 I = ISTOR(NUM)      TYPE = IDATA(I)      IF (TYPE .LE. 0 .OR. TYPE .GE. 50) GO TO 5200      CALL SKETCH(NUM)      CALL DEPICT      IF (.NOT. ATWE) GO TO 5200      IF (TYPE .EQ. 4) GO TO 400      IF (TYPE .EQ. 5) GO TO 500      IF (TYPE .EQ. 6) GO TO 600      IF (TYPE .EQ. 8) GO TO 800      IF (TYPE .EQ. 9) GO TO 900      IF (TYPE .EQ. 24) GO TO 2400      IF (TYPE .EQ. 28 .OR. TYPE .EQ. 29) GO TO 2800      IF (TYPE .EQ. 31) GO TO 3100      IF (TYPE .EQ. 37) GO TO 3700      GO TO 5200CC     4. -- BENDING MAGNETC  400 IF (ALO(1)) THEN        NMIS = NM4        IMIS = ISTOR(NMIS)        TYT = INT(DATA(IMIS+7))        LTAB = MOD(TYT/10,10)        IF (LTAB .EQ. 1) THEN          IF (NM .LT. 10) THEN            NM = NM + 1            NMTE(NM) = NUM          ENDIF        ENDIF      ENDIF      GO TO 5200CC     5. -- QUADRUPOLEC  500 IF (ALO(2)) THEN        NMIS = NM5        IMIS = ISTOR(NMIS)        TYT = INT(DATA(IMIS+7))        LTAB = MOD(TYT/10,10)        IF (LTAB .EQ. 1) THEN          IF (NM .LT. 10) THEN            NM = NM + 1            NMTE(NM) = NUM          ENDIF        ENDIF      ENDIF      GO TO 5000CC     6. -- UPDATEC  600 IF (.NOT. ATWE) GO TO 5200      NSLIT = INT(DATA(I+1))      IF (NSLIT .EQ. 0) THEN        IUP = INT(DATA(I+2))        NUP(IUP+1) = NUM        LAKE = 0        IADR = I + IPTOJ(4)        DATA(IADR) = FAKE      ENDIF      GO TO 5200CC     8. -- MISALIGNMENTC  800 TYT = INT(DATA(I+7))      LFM = TYT/100      LTAB = MOD(TYT/10,10)      RORC = MOD(TYT,10)      IR = RORC + 1      IF (LTAB .EQ. 1 .AND. RORC .LE. 2 .AND. NM .LT. 10) THEN        NM = NM + 1        NMTE(NM) = NUM      ENDIF      IF (RORC .GE. 3) GO TO 820      IF (RORC .EQ. 0) GO TO 5200      NUMS = NUP(IR)      IF (NUMS .EQ. 0) THEN        IF (LFM .EQ. 0) GO TO 5200        NUPS = NIU(IR)        NUPS = NUPS + 1        NIU(IR) = NUPS        NIM(IR,NUPS) = NUM      ELSE        IM = ISTOR(NUMS)        TYPES = IDATA(IM)        IF (LFM .NE. 0 .OR. TYPES .NE. 6) THEN          CALL SKETCH(NUMS)          IADR = IM + IPTOJ(4)          NUPS = IDATA(IADR)          NUPS = NUPS + 1          LAKE = NUPS          DATA(IADR) = FAKE          LAKE = NUM          DATA(IADR+NUPS) = FAKE        ENDIF      ENDIF      GO TO 5200C  820 IF (RORC .EQ. 3 .OR. RORC .EQ. 4) THEN        ALO(1) = .TRUE.        NM4 = NUM      ENDIF      IF (RORC .EQ. 3 .OR. RORC .EQ. 5) THEN        ALO(2) = .TRUE.        NM5 = NUM      ENDIF      GO TO 5200CC     9. -- REPEATC  900 NREP = IDATA(I+1)      CALL REPEAT1      IF (FLUSHL) GO TO 5300      GO TO 5200CC     24. -- DEFINED SECTIONC 2400 JDEF = IDATA(I+1)      IF (JDEF .EQ. 3 .OR. JDEF .EQ. 4) THEN        NADDEF(1) = IDATA(I+2)        NADDEF(2) = IDATA(I+3)      ENDIF      CALL DEFINE      IF (FLUSHL) GO TO 5300      GO TO 5200CC     28. -- RECTANGULAR BENDING MAGNETC            ORC     29. -- WEDGE BENDING MAGNETC 2800 IF (ALO(1)) THEN        NMIS = NM4        IMIS = ISTOR(NMIS)        TYT = INT(DATA(IMIS+7))        LTAB = MOD(TYT/10,10)        IF (LTAB .EQ. 1) THEN          IF (NM .LT. 10) THEN            NM = NM + 1            NMTE(NM) = NUM          ENDIF        ENDIF      ENDIF      GO TO 5000C                C     31. -- POSITION MARKERC 3100 DRC = .FALSE.      NMARKS = IDATA(I+1)      CALL AGENDA(1)      GO TO 5200CC     37. -- ALIGNMENT MARKERC 3700 IF (.NOT. ATWE) GO TO 5200      NSLIT = INT(DATA(I+1))      IF (NSLIT .EQ. 0) THEN        IUP = INT(DATA(I+2))        NUP(IUP+1) = NUM        LAKE = 0        IADR = I + IPTOJ(4)        DATA(IADR) = FAKE      ENDIF      GO TO 5200CC     LOOP THROUGH MISALIGNMENTS BY NAMEC 5000 IF (NMISRB .NE. 0) CALL AGENDR(1)CC     ADVANCE TO NEXT ELEMENTC 5200 IF (MKG .AND. NUM .EQ. NMARKE) CALL AGENDA(2)      IF (ALGR .AND. NUM .EQ. NMISRE) CALL AGENDR(2)      NUM = NUM + NDIF      IF (.NOT. MKG .AND. NUSE .NE. 0 .AND. NUM .GT. NUSE) GO TO 5300      IF (NUM .LE. NEL) GO TO 10C 5300 NMMAX = NM      RETURN      END